"""Inorder and level order verification helper."""

from typing import List
from node import BLACK, RED, RBNode
from rb_tree import RedBlackTree


class RBValidator:
    @staticmethod
    def validate_invariants(tree: RedBlackTree) -> bool:
        if not tree.root:
            return True
        if tree.root.color != BLACK:
            return False

        def check_node(node: RBNode) -> tuple[bool, int]:
            if not node:
                return True, 1
            # No two consecutive RED nodes
            if node.color == RED:
                if node.left and node.left.color == RED:
                    return False, 0
                if node.right and node.right.color == RED:
                    return False, 0
            ok_l, bh_l = check_node(node.left)
            ok_r, bh_r = check_node(node.right)
            if not ok_l or not ok_r or bh_l != bh_r:
                return False, 0
            return True, bh_l + (1 if node.color == BLACK else 0)

        valid, _ = check_node(tree.root)
        return valid

